const hoje = new Date();

const inicioDoDia = new Date(
  hoje.getFullYear(),
  hoje.getMonth(),
  hoje.getDate()
);

const fimDoDia = new Date(
  hoje.getFullYear(),
  hoje.getMonth(),
  hoje.getDate() + 1
);

// Etapas permitidas do OUTBOUND
const etapasOutbound = [
  11, // Novo Lead OB
  6,  // Leads qualificados
  7,  // Contato inicial OB
  39, // Pós Contato Phillips
  9,  // Pós Contato RM Outras Marcas
  12, // Agendamento / reagendamento OB
  8   // Follow-up quente
];

return items.filter(item => {
  const addTime = item.json.add_time;
  const stageId = Number(item.json.stage_id);

  // Sem data de criação
  if (!addTime) {
    return false;
  }

  const dataAdicao = new Date(addTime);

  // Adicionado hoje
  const adicionadoHoje =
    dataAdicao >= inicioDoDia &&
    dataAdicao < fimDoDia;

  // Está em uma etapa do OUTBOUND
  const etapaOutbound = etapasOutbound.includes(stageId);

  return adicionadoHoje && etapaOutbound;
});

const camposIgnorados = [
  '26.313.383/0001-41'
];

const resultado = [];

for (const item of $input.all()) {
  const dados = item.json;

  const camposVazios = Object.entries(dados)
    .filter(([campo, valor]) => {
      if (camposIgnorados.includes(campo)) return false;

      return valor === '' || valor === null || valor === undefined;
    })
    .map(([campo]) => campo);

  if (camposVazios.length > 0) {
    resultado.push({
      id: dados.ID,
      nome: dados.Nome,
      instituicao: dados['Instituição'],
      cnpj: dados.CNPJ,
      camposVazios
    });
  }
}

let mensagem = '';

if (resultado.length === 0) {
  mensagem = `
    <h2>Todos os leads estão completos</h2>
    <p>Nenhum lead possui campos vazios.</p>
  `;
} else {
  mensagem = `
    <h2>Leads com campos vazios</h2>
    <p>Foram encontrados <strong>${resultado.length}</strong> leads com informações pendentes.</p>

    <table border="1" cellpadding="8" cellspacing="0" style="border-collapse: collapse;">
      <thead>
        <tr>
          <th>ID</th>
          <th>Nome</th>
          <th>Instituição</th>
          <th>CNPJ</th>
          <th>Campos vazios</th>
        </tr>
      </thead>
      <tbody>
  `;

  for (const lead of resultado) {
    mensagem += `
      <tr>
        <td>${lead.id ?? ''}</td>
        <td>${lead.nome ?? ''}</td>
        <td>${lead.instituicao ?? ''}</td>
        <td>${lead.cnpj ?? ''}</td>
        <td>${lead.camposVazios.join(', ')}</td>
      </tr>
    `;
  }

  mensagem += `
      </tbody>
    </table>
  `;
}

return [
  {
    json: {
      total: resultado.length,
      mensagem
    }
  }
];

